LOCK TABLES `fight` WRITE;
/*!40000 ALTER TABLE `fight` DISABLE KEYS */;
INSERT INTO `fight` VALUES ('反击','当一个生物在一次对你进行的近战攻击中失手，你可以使用你的反应并消耗一颗卓越骰以对该生物进行一次近战武器攻击。若你命中，则你将卓越骰加入该攻击的伤害骰中。'),('快手投掷','以一个附赠动作，你能消耗一枚卓越骰一一件具有投掷属性的武器进行一次远程攻击。在进行此攻击时，你能拔出一把投掷武器作为攻击的一部分。如果此次攻击命中，你能将消耗的卓越骰加入此次攻击的伤害骰中。'),('恐吓击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以尝试吓唬目标。你将卓越骰加入该攻击的伤害骰中，且目标必须进行一次感知豁免。若豁免失败，它将因你陷入恐惧直到你的下个回合结束。'),('战术预估','当你进行一次智力（调查）、智力（历史）或感知（洞悉）检定时，你能够消耗一枚卓越骰，将消耗的卓越骰加入此次属性检定中。'),('扰乱击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以干扰该生物，为你的盟友制造良机。你将卓越骰加入该攻击的伤害骰中。在你的下个回合开始前，下一次你以外的攻击者对目标所进行的攻击检定将具有优势。'),('指挥官奇袭','当你在你的回合采取攻击动作时，你可以放弃你的其中一次攻击，并使用一个附赠动作以指挥你的其中一个同伴进行奇袭。当你这么做时，选择一个能够看见或听见你的友善生物，并消耗一颗卓越骰。该生物可以立刻使用它的反应以进行一次武器攻击，并将卓越骰加入该攻击的伤害骰中。'),('挑衅击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以尝试挑衅目标攻击你。你将卓越骰加入该攻击的伤害骰中，且目标必须进行一次感知豁免。若豁免失败，则直到你的下个回合结束前，目标对你以外的对象所进行的所有攻击检定都将承受劣势。'),('推撞击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以尝试驱使目标后退。你将卓越骰加入该攻击的伤害骰中，且若目标的体型为大型或更小，则它必须进行一次力量豁免。若豁免失败，你将目标推离你最多15尺距离。'),('擒拿击','当你在一次近战武器攻击命中一个生物后，你能够立即消耗一枚卓越骰，以一个附赠动作对目标进行一次擒抱（见《玩家手册》的\"擒抱\"规则）。将消耗的卓越骰加入你的力量（运动）检定中。'),('格挡','当另一个生物以一次近战攻击伤害你时，你可以使用你的反应并消耗一颗卓越骰以减少伤害。该伤害将减少等同于你卓越骰所骰出的数字 + 你的敏捷调整值。'),('横扫击','当你以一次近战武器攻击命中一个生物时，你可以消耗一颗卓越骰以尝试以相同的攻击伤害另一个生物。选择另一个距离原本目标5尺内，且处于你触及范围的生物。若原本的攻击检定能够命中第二个生物，则它将受到等同于你卓越骰所骰出的数字的伤害。这个伤害的伤害类型与原本攻击所造成的伤害类型相同。'),('灵动击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以调动你其中一个伙伴到一处更有利的位置。你将卓越骰加入该攻击的伤害骰中，且你选择一个能够看见或听见你的友善生物。该生物可以使用它的反应以移动最多等同于它移动速度一半的距离，且不会触发来自你攻击目标的借机攻击。'),('突刺击','当你在你的回合进行一次近战武器攻击时，你可以消耗一颗卓越骰以使你该攻击的触及范围增加5尺。若你命中，则你将卓越骰加入该攻击的伤害骰中。'),('突袭','当你进行一次敏捷（隐匿）检定或先攻检定时，如果你并非无力，你能够消耗一枚卓越骰，并将消耗的卓越骰加入检定中。'),('精准击','当你对一个生物进行一次武器攻击检定，你可以消耗一颗卓越骰以将它加入该检定中。你可以在进行攻击检定之前或之后使用此战技，但必须在任何攻击的效果适用前使用。'),('绊摔击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰以尝试将目标击倒。你将卓越骰加入该攻击的伤害骰中，且若目标的体型为大型或更小，则它必须进行一次力量豁免。若豁免失败，则你将目标击倒伏地。'),('缴械击','当你以一次武器攻击命中一个生物时，你可以消耗一颗卓越骰并尝试使目标缴械，强迫它掉落一个它正持握且你所选择的物品。你将卓越骰加入该攻击的伤害骰中，且目标必须进行一次力量豁免。若豁免失败，它将掉落你所选择的该物体。该物体将落在它的脚边。'),('警戒','当一个生物移动进你的触及范围而你手握武器时，你能以一个反应消耗一枚卓越骰对该生物进行一次武器攻击。如果攻击命中，将消耗的卓越骰加入此次攻击的伤害骰中。'),('诡诈击','你可以消耗一颗卓越骰并在你的回合使用一个附赠动作以进行佯攻，选择一个距离你5尺内的生物作为你的目标。你在该回合对该生物的下一次攻击检定中具有优势。若该攻击命中，则将卓越骰加入该攻击的伤害骰中。\n\n若你在获得这个优势的回合中没有使用它，则你将会失去这个优势。'),('诱饵战术','当你距离一个生物5尺以内时，你能够消耗一枚卓越骰，如果你同时消耗至少5尺的移动速度，该生物自愿且并不无力，你能与该生物互换位置。这一移动不会引发借机攻击。\n\n掷消耗的卓越骰。直到你的下个回合开始，你或另一个生物（由你选择）的AC获得等于掷骰结果的加值。'),('躲闪步伐','当你移动时，你可以消耗一颗卓越骰，掷该卓越骰并将骰出的数字加入你的AC中直到你停止移动。'),('领导风范','当你进行一次魅力（威吓）、魅力（表演）或魅力（说服）检定时，你能够消耗一枚卓越骰，将消耗的卓越骰加入此次属性检定中。'),('鼓舞','在你的回合，你可以使用一个附赠动作并消耗一颗卓越骰以鼓舞你其中一个同伴的士气。当你这么做时，选择一个能够看见或听见你的友善生物。该生物将获得等同于你卓越骰所骰出的数字 + 你的魅力调整值的临时生命值。');
/*!40000 ALTER TABLE `fight` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hero`
--

DROP TABLE IF EXISTS `hero`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hero` (
  `id` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `sex` varchar(5) NOT NULL,
  `age` varchar(30) NOT NULL,
  `race` varchar(30) NOT NULL,
  `career` varchar(30) NOT NULL,
  `attribute` varchar(50) NOT NULL,
  `sum` int NOT NULL,
  `camp` varchar(10) NOT NULL,
  `skill` varchar(100) DEFAULT NULL,
  `tool` varchar(300) DEFAULT NULL,
  `equip` varchar(300) DEFAULT NULL,
  `language` varchar(300) DEFAULT NULL,
  `feat` varchar(300) DEFAULT NULL,
  `save` varchar(50) NOT NULL,
  `money` int NOT NULL,
  `spell0` varchar(300) DEFAULT NULL,
  `spell1` varchar(300) DEFAULT NULL,
  `spell2` varchar(300) DEFAULT NULL,
  `pray` varchar(30) DEFAULT NULL,
  `style` varchar(30) DEFAULT NULL,
  `superspell` varchar(30) DEFAULT NULL,
  `fight` varchar(30) DEFAULT NULL,
  `other` varchar(500) DEFAULT NULL,
  `live` varchar(10) NOT NULL,
  `favorite` tinyint(1) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

