INSERT INTO `name` VALUES ('伊路斯坎人','安德,布拉特,布兰,夫拉夫,盖斯,兰德,鲁特,玛尔瑟,斯托尔,塔曼,厄斯','阿玛芙里,贝塔,瑟菲莉,凯芙拉,玛拉,奥尔加,斯莉芙里,维丝特拉','布莱特伍德,赫尔德,霍尔雷玟,拉克曼,斯托维恩,文德瑞瓦',NULL),('卡林珊人','阿瑟尔,巴迪德,哈瑟德,科麦德,梅赫门,殊德曼,扎希尔','阿塔拉,赛蒂尔,哈玛,嘉丝摩,梅利尔,丝帕拉,雅希拉,扎希达','巴沙,德迈恩,嘉衫,哈利德,莫斯塔娜,帕沙尔,雷因',NULL),('受国人','安,陈,齐,费,江,军,连,朗,蒙,温,单,水,文','白,周,佳,蕾,梅,乔,水,泰','犬,黄,高,宫,劳,林,梅,彬,申,森,谭,万',NULL),('名-侏儒','奥斯顿,艾尔文,包迪拿,布洛克,布里高,丁宝,埃尔登,埃尔基,方克林,弗鲁格,杰儿博,葛尔宝,格林,杰比多,凯伦,南富多,奥莱,朗达,喜宝,辛德里,沃莱恩,雷恩,朱克','彬娜汀,布瑞娜,卡拉蜜,卡琳,唐尼拉,杜法米,艾拉,艾利卓贝,艾利薇,莉莉,露莫汀,罗瑞拉,玛娜布,尼莎,奈克斯,奥达,奥尔拉,洛伊维,夏蜜尔,塔娜,维渥琪,扎娜','贝伦,德哥,福克,加立克,那可,摩宁,宁哥,罗那,夏本,廷伯斯,图兰','麦酒,灰炉,獾,斗篷,双锁,小泥棒,镊子,古,偷儿,单鞋,麻子,闪光宝石,跛鸭'),('名-兽人','丹契,锋,嘎尔,哼克,豪格,伊姆吁,凯斯,库斯克,穆赫雷,隆特,夏普,梭克','巴姬,爱门,恩红,坎西芙,美弗,妮加,欧娃,欧玟卡,小叉,苏塔,芙拉,芙伦,伊瓦达',NULL,NULL),('名-半身人','阿尔顿,安德,卡德,柯林,艾尔顿,埃里奇,芬南,盖瑞,林逹尔,里尔,梅里克,米罗,欧斯朋,佩林,威德,罗斯科,韦尔比\n\n','安德妮,布妮,卡莉,蔻拉,尤菲米娅,吉莉安,卡芙里,拉薇妮亚,莉达,玛拉,奈达,佩拉,波蒂亚,瑟拉菲娜,希尔娜,赛研,梵妮,薇娜\n\n','集刷,良桶,绿瓶,高丘,垮丘,无纪,茶叶,刺子,投石,枝底',NULL),('名-吉斯泽莱','达克,杜尔斯,弗兹斯,格雷斯,胡姆,卡拉,穆尔格,努姆,斯拉卡,索姆\n\n','阿达卡,阿德亚,埃拉,埃泽利亚,伊米津,伊泽拉,贾纳拉,洛拉亚,乌维亚,维斯卡\n\n',NULL,NULL),('名-吉斯洋基','伊利拉丹,加斯,贾阿多克,卡瑞纳斯,莱卡斯,奎斯,瑞萨安,特罗波斯,维兰,萨莫达斯','阿瑞尔,比努尔,费内尔齐伊,珍利格,帕赫泽,奎尔斯提尔,西鲁斯,瓦伊拉,耶松,扎尔瑞斯',NULL,NULL),('名-天狗','重击者,敲击者,切裂者,猛击者,鼠挠者,呼哨者,捕鼠者,低哮者,扬帆者,锤打者,切割者','重击者,敲击者,切裂者,猛击者,鼠挠者,呼哨者,捕鼠者,低哮者,扬帆者,锤打者,切割者',NULL,NULL),('名-斑猫人','山巅云,小云,五木梁,阿梁,玉鞋,小玉,左撇蜂鸟,阿鸟,七雷云,雷,蛇裙带,蛇蛇,迷烟镜,镜','山巅云,小云,五木梁,阿梁,玉鞋,小玉,左撇蜂鸟,阿鸟,七雷云,雷,蛇裙带,蛇蛇,迷烟镜,镜','亮崖,远雨,山树,啸河,鼾山',NULL),('名-梭螺鱼人','科鲁斯,德尔尼斯,基马斯,凯罗斯,莫洛斯,纳洛斯,沃多斯,祖尼斯','艾琳,贝尔辛,杜辛,菲洛伦,奥塔宁,莎琳,薇琳,沃琳','阿洛尔萨斯,普马纳斯,伍瓦克萨思',NULL),('名-歌利亚','奥坎,埃格拉斯,盖-阿尔,高萨克,伊利坎,基奥西,库奥里,洛-卡格,曼内奥,马维斯,纳拉,奥里洛,帕武,佩萨尼,萨莱,索萨姆,乌萨尔,沃内亚,维马克','奥坎,埃格拉斯,盖-阿尔,高萨克,伊利坎,基奥西,库奥里,洛-卡格,曼内奥,马维斯,纳拉,奥里洛,帕武,佩萨尼,萨莱,索萨姆,乌萨尔,沃内亚,维马克','阿纳卡拉萨伊,埃拉尼西诺,加萨卡纳西,卡拉贾诺,卡索-奥拉维,科莱-吉莱纳,奥戈拉卡努,苏利亚加,图努卡拉西,瓦伊梅-拉加\n\n','屠熊者,唤晓者,无畏者,寻燧者,角刻者,锐眼者,独猎者,远跃者,碎根者,观天者,稳手者,绞线者,遗孤,曲肢者,绘语者'),('名-矮人','阿德里克,阿贝里希,巴恩,巴伦德,布洛托,布鲁诺,达因,达拉克,德尔格,艾帕克,因克,法格林,弗林特,加代因,哈比克,基尔德拉克,莫格兰,欧斯克,奥斯卡,朗格琳,鲁瑞克,塔可林,索拉丁,索林,托达克,特若本,特拉沃克,伍夫加,维特,冯达尔\n\n','安珀,爱汀,欧德希德,巴德莱恩,达格娜,黛萨,艾尔德芙,法尔克伦,菲涅伦,冈罗妲,古尔蒂斯,赫尔嘉,贺琳,卡夫拉,克丽丝莱德,伊尔蒂,丽芙拉萨,玛德雷德,丽丝怀恩,珊诺,托贝拉,托嘉,维斯特拉','巴尔德克,战锤,布劳南威尔,丹吉尔,火铸,霜须,果伦,豪德赫克,铁拳