INSERT INTO `pray` VALUES ('暗影护甲',0,NULL,NULL,1,'你可以对你自己随意施放法师护甲，无需消耗法术位或材料构材。'),('斥力冲击',1,NULL,NULL,1,'当你使用魔能爆命中一个生物时，你可以直线推动该生物远离你最多10尺。'),('怠惰之枪',1,NULL,NULL,1,'在你的每个回合一次，当你使用你的魔能爆命中一个生物时，你可以让该生物的移动速度降低10尺，持续直到你的下个回合结束。'),('符文师之眼',0,NULL,NULL,0,'你可以读懂所有文本。'),('哈达之攫',1,NULL,NULL,1,'在你的每个回合一次，当你使用你的魔能爆命中一个生物时，你可以让该生物向你直线移动10尺。'),('联心之视',0,NULL,NULL,0,'你可以使用你的动作以触碰一个自愿的类人生物，并直到你的下个回合结束前通过它的感官感知周遭。只要该生物和你处于相同的存在位面，你就可以在后续的回合中使用你的动作以维持这道链接，将持续时间延长到你的下个回合结束。当通过该生物的感官感知时，你得益于该生物所拥有的任何特殊感官，且你对你自己的周遭环境视作耳聋和目盲。'),('迷人影响力',0,'欺瞒,说服',NULL,0,NULL),('迷雾幻影',0,'无声幻影',NULL,1,'你可以随意施放无声幻影，无需消耗法术位或材料构材。'),('魔鬼视觉',0,NULL,NULL,0,'当你在黑暗中，无论是魔法还是非魔法黑暗，你可以正常看见距离你120尺范围内的事物。'),('魔能视界',0,'侦测魔法',NULL,1,'你可以随意施放侦测魔法，无需消耗法术位。'),('魔能意志',0,NULL,NULL,0,'你在用于维持法术专注的体质豁免上具有优势。'),('魔能之矛',1,NULL,NULL,1,'当你施放魔能爆，它的射程变为300尺。'),('千面之脸',0,'易容术',NULL,1,'你可以随意施放易容术，无需消耗法术位。'),('痛苦冲击',1,NULL,NULL,1,'当你施放魔能爆，在命中时将你的魅力调整值加入它所造成的伤害。'),('五运窃贼',0,NULL,NULL,1,'你可以使用契术师法术位施放一次灾祸术。直到你完成一次长休之前你都不能再这么做。'),('邪魔精力',0,NULL,NULL,1,'你可以对你自己以1环法术随意施放摹造生命，无需消耗法术位或材料构材。'),('野兽之语',0,'动物交谈术',NULL,1,'你可以随意施放动物交谈术，无需消耗法术位。');
/*!40000 ALTER TABLE `pray` ENABLE KEYS */;
UNLOCK TABLES;

