-- Dumping data for table `style`
--

LOCK TABLES `style` WRITE;
/*!40000 ALTER TABLE `style` DISABLE KEYS */;
INSERT INTO `style` VALUES ('决斗',NULL,'当你单手持用一把近战武器，且没有持用其他武器时，你在使用该武器所进行的伤害骰中获得+2加值。'),('卓越技巧','59','你从战斗大师武术范型的战技列表中习得一项战技。如果该战技需要豁免，则豁免DC为8 + 你的熟练加值 + 你的力量或敏捷调整值（由你选择）。\n\n你获得一个d6的卓越骰（此卓越骰与任何你能够其他方式获得的卓越骰累计）。此卓越骰可用于启动你的战技。卓越骰一经使用即消耗，并在完成一次短休或长休后恢复。'),('双武器战斗',NULL,'当你进行双武器战斗时，你可以将你的属性调整值加入第二次攻击的伤害中。'),('守护',NULL,'当一个你所能看见的生物攻击一个距离你5尺内你以外的目标，你可以使用你的反应以让该攻击检定承受劣势。你必须持握一面盾牌。'),('巨武战斗',NULL,'当你在使用一把以双手持用的近战武器所进行攻击的伤害骰中骰出了1或2的结果，你可以重骰该骰，且必须使用新的掷骰结果，即使其结果仍然是1或2。该武器必须具有双手或可双手属性才能让你获得这个好处。'),('弓道',NULL,'你在使用远程武器进行的攻击检定中获得+2加值。'),('徒手格斗',NULL,'你的徒手打击可以造成1d6 + 你力量调整值的钝击伤害，如果你没有手持任何武器或盾牌进行攻击，伤害骰从d6变为d8。\n\n你的每个回合开始时，你可以对被擒于你的一个生物造成1d4钝击伤害。'),('投掷武器战斗',NULL,'你可以在使用一件带有投掷属性武器进行进攻时，将那件武器作为攻击的一部分而拔出。\n\n此外，在你以一件投掷武器于远程攻击中命中对手时，你的伤害骰获得+2加值。'),('拦截',NULL,'当一个你可见的生物攻击距离你5尺以内你以外的目标时，你能以一个反应将目标受到的伤害减少1d10 + 你熟练加值（最多减到0伤害）。当你手持一面盾牌或者一把简单或军用武器时才能执行此反应。'),('盲斗',NULL,'你获得10尺盲视。在10尺范围内，你可以看见除了处于全遮掩后的任何东西，哪怕你正在被目盲或是在黑暗之中。此外，你可以看见该范围内的未对你成功躲藏的隐形生物。'),('防御',NULL,'当你穿戴护甲时，你的AC获得+1加值。');
/*!40000 ALTER TABLE `style` ENABLE KEYS */;
UNLOCK TABLES;

