INSERT INTO `superspell` VALUES ('升阶法术','当你施放一个会强迫一个生物进行豁免检定以抵抗它效果的法术时，你可以消耗3点术法点以让一个该法术的目标在它对抗该法术的第一次豁免检定中承受劣势。'),('孪生法术','当你施放一个射程不为自身，且在使用当前法术位时无法指定超过一个生物作为目标的法术时，你可以消耗等同于该法术环阶数量的术法点以使用同个法术指定射程内的第二个生物作为目标（若该法术为戏法，则消耗1点术法点）。\n\n要符合条件，该法术必须要在使用当前法术位时无法指定超过一个生物作为目标。举例来说，魔法飞弹和灼热射线并不符合条件，但冷冻射线和幻色法球则可。'),('延时法术','当你施放一个持续时间为1分钟或更久的法术时，你可以消耗1点术法点以将它的持续时间变为二倍，最久到24小时。'),('强效法术','当你在为法术骰伤害时，你可以消耗1点术法点以重骰最多等同于你魅力调整值数量的骰子（最少一颗）。你必须使用新的掷骰结果。\n\n即使你已经在施放此法术的期间已经使用了一个不同的超魔法选项，你仍然可以使用强效法术。'),('瞬发法术','当你施放一个施法时间为1个动作的法术时，你可以消耗2点术法点以将它在这次施法的的施法时间变为1个附赠动作。'),('精妙法术','当你施放一个法术时，你可以消耗1点术法点以施放它而无须提供任何姿势或声音构材。，你可以消耗2点术法点以将它在这次施法的的施法时间变为1个附赠动作。'),('谨慎法术','当你施放一个会强迫其他生物进行豁免检定的法术时，你可以保护其中一些生物不受该法术的完整威力影响。要这么做，你得消耗1点术法点，并选择最多等同于你魅力调整值数量的生物（最少一个生物）。被选择的生物将在对抗该法术的豁免检定中自动成功。'),('转化法术','当你施放一个能够造成以下列表中类型伤害的法术时，你可以使用1术法点将其改为列表中的另一种伤害类型：强酸、冷冻、火焰、闪电、毒素或雷鸣。'),('远程法术','当你施放一个射程为5尺或更远的法术时，你可以消耗1点术法点以将该法术的射程变为二倍。\n\n当你施放一个射程为触碰的法术时，你可以消耗1点术法点以将该法术的射程变为30尺。'),('追踪法术','当你因法术进行一次攻击检定并失手时，你可以使用2术法点重投d20。你必须使用重投的结果。\n\n超魔法追踪法术可以与其他超魔法选项合用。');
/*!40000 ALTER TABLE `superspell` ENABLE KEYS */;
UNLOCK TABLES;

